      music = "bq_15048_voice",
      renwu = "npc",
      role1 = 4183000,
      role2 = 4183111,
      role3 = 403203,
      role5 = 4183401,
      sentence = "在白起没有承认过的岁月里，我还是会在心里把他偷偷纳为“伙伴”，又或者某个我不知道要如何形容的存在。",
      next = {101}
    },
    [101] = {
