      music = "bq_15048_voice",
      renwu = "npc",
      role1 = 4183000,
      role2 = 4183111,
      role3 = 403203,
      role5 = 4183401,
      roleanim = 1.1,
      sentence = "他的脸上没有任何表情，我蹲了下来，认真注视着那双漂亮的眼睛。",
      next = {102}
    },
    [102] = {
      beijing = 4955,
      dhead = 101,
      dialog = 1,
      music = "bq_15048_voice",
      renming = "$u",
      renwu = "npc",
      role1 = 4183000,
      role2 = 4183111,
      role3 = 403203,
      role5 = 4183401,
      roleanim = 1.1,
      sentence = "这件事我从来没告诉过任何人，但现在我愿意把这个小小的秘密分享给你。",
      next = {103}
    },
    [103] = {
      beijing = 4955,
      dhead = 107,
