      renwu = "npc",
      role1 = 4183000,
      role2 = 4183111,
      role3 = 403203,
      role5 = 4183401,
      roleanim = 1.1,
      sentence = "你知道吗，听说这个世界上有一个非常美好的城市，它叫恋语市。",
      next = {104}
    },
    [104] = {
      beijing = 4955,
      dhead = 107,
