      renwu = "npc",
      role1 = 4183000,
      role2 = 4183111,
      role3 = 403203,
      role5 = 4183401,
      roleanim = 1.1,
      sentence = "那里没有战争，也没有辐射，大海和天空也都是蓝色的，不像我们这样红红的一片。",
      next = {105}
    },
    [105] = {
