      renwu = "npc",
      role1 = 4183000,
      role2 = 4183111,
      role3 = 403203,
      role5 = 4183401,
      roleanim = 1.1,
      sentence = "我也承认我确实参加过中洋战争，也见过你，不过我没你想得那么厉害。",
