  [640053] = {
    [1] = {
      beijing = 1261,
      dialog = 3,
      music = "11_Sorrow_LongEnding_Ver",
      renwu = "npc",
      sentence = "After that day, Gavin and I would split up and work separately to gather info about Neo and Wendy.",
