    },
    [2] = {
      beijing = 1261,
      dialog = 3,
      music = "11_Sorrow_LongEnding_Ver",
      renwu = "npc",
      sentence = "A few days later, we met in a cafe to exchange our findings.",
      next = {3}
    },
    [3] = {
