      dhead = 308,
      dialog = 1,
      music = "11_Sorrow_LongEnding_Ver",
      renming = "$u",
      renwu = "npc",
      sentence = "I talked to an old teacher at the deaf school. He said Neo didn't know sign language when he first enrolled, and that he was all sullen and quiet.",
      next = {4}
    },
    [4] = {
      beijing = 1261,
      dhead = 308,
      dialog = 1,
      music = "11_Sorrow_LongEnding_Ver",
      renming = "$u",
      renwu = "npc",
      sentence = "Only Wendy would talk to him. And she taught him sign language after school.",
      next = {5}
    },
    [5] = {
      beijing = 1261,
      dhead = 307,
      dialog = 1,
      music = "11_Sorrow_LongEnding_Ver",
      renming = "$u",
      renwu = "npc",
      sentence = "After finding out he loved painting, she used her pocket money to buy him brushes and paper without her parents' knowledge.",
      next = {6}
    },
    [6] = {
      beijing = 1261,
      dhead = 301,
      dialog = 1,
      music = "11_Sorrow_LongEnding_Ver",
      renming = "$u",
      renwu = "npc",
      sentence = "They were happy at the school. Neo even held a small art exhibition there that was attended by lots of students and teachers.",
      next = {7}
    },
    [7] = {
      beijing = 1261,
      dhead = 306,
      dialog = 1,
      music = "11_Sorrow_LongEnding_Ver",
      renming = "$u",
      renwu = "npc",
      sentence = "It was after graduation he things got hard for him.",
      next = {8}
    },
    [8] = {
      beijing = 1261,
      dialog = 3,
      music = "11_Sorrow_LongEnding_Ver",
      renwu = "npc",
      sentence = "He had no place to live and couldn't find a job. Unlike Wendy who could rely on her parents, Neo was on his own.",
      next = {9}
    },
    [9] = {
      beijing = 1261,
      dhead = 306,
      dialog = 1,
      music = "11_Sorrow_LongEnding_Ver",
      renming = "$u",
      renwu = "npc",
      sentence = "Wendy would continue to use her parents' money to buy painting supplies for Neo. The two even set up a stall on the street selling finished paintings.",
      next = {10}
    },
    [10] = {
      beijing = 1261,
      dhead = 305,
      dialog = 1,
      music = "11_Sorrow_LongEnding_Ver",
      renming = "$u",
      renwu = "npc",
      sentence = "But they didn't make a dime.",
