      renwu = "npc",
      role1 = 4103000,
      role2 = 403111,
      role3 = 403203,
      role5 = 4103401,
      sentence = "Not long after he joined, the company was reported for illegal fundraising. He and his boss ended up spending three years in prison.",
      next = {14}
    },
